import{c as t,Q as a,j as r,m as i}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"MOC: Multi-Order Communication in LLM-based Multi-Agent Systems","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.02359","title":"MOC: Multi-Order Communication in LLM-based Multi-Agent Systems","archived_date":"2026-07-17T00:00:00.000Z","arxiv_id":2606.02359,"authors":["Yao Guan","Lin Wang","Zhihu Lu","Ziyi Wang","Wenzhu Yan","Qiang Duan"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2606.02359v1","pdf_path":"pdfs/2606.02359.pdf","published_date":"2026-06-01T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-01-moc-multi-order-communication-multi-agent-2606-02359.md","filePath":"research/papers/2026-06-01-moc-multi-order-communication-multi-agent-2606-02359.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-06-01-moc-multi-order-communication-multi-agent-2606-02359.md"};function n(s,e,l,c,u,d){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="moc-multi-order-communication-in-llm-based-multi-agent-systems" tabindex="-1">MOC: Multi-Order Communication in LLM-based Multi-Agent Systems <a class="header-anchor" href="#moc-multi-order-communication-in-llm-based-multi-agent-systems" aria-label="Permalink to &quot;MOC: Multi-Order Communication in LLM-based Multi-Agent Systems&quot;">​</a></h1><p><strong>Authors</strong>: Yao Guan, Lin Wang, Zhihu Lu, Ziyi Wang, Wenzhu Yan, Qiang Duan <strong>Published</strong>: June 1, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.02359" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.02359</a> · <a href="https://arxiv.org/html/2606.02359v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.02359 <strong>Categories</strong>: cs.AI <strong>Code</strong>: <a href="https://github.com/yao-guan/MOC" target="_blank" rel="noreferrer">https://github.com/yao-guan/MOC</a><strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.02359" target="_blank" rel="noreferrer">research/papers/pdfs/2606.02359.pdf</a></p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Despite the remarkable progress of Large Language Model (LLM) based Multi-Agent Systems, most research focuses on optimizing coordination topology while largely underexploring the equally critical problem: how to transmit and optimize messages among agents effectively? Current communication schemes typically rely on the direct concatenation of first-order neighbor responses, which induces a restricted evidence receptive field and leads to the dilution of crucial insights over multi-hop paths. To address these limitations, we propose the Multi-Order Communication (MOC) scheme, which reconstructs the inter-agent communication to capture multi-hop dependencies and incorporates a structural message consolidation strategy to ensure efficiency. Specifically, we formalize the communication mechanism to construct a structured multi-order evidence stream, and subsequently design a Semantic-Topological Merging algorithm to optimize semantic fidelity within token constraints. Extensive experiments across six diverse datasets and LLM backbones of varying parameter scales demonstrate that MOC consistently improves task performance and reduces communication costs.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>指出 MAS 研究偏重拓樸、忽視「訊息本身如何傳輸與優化」；一階鄰居直接串接導致 evidence receptive field 受限、關鍵洞見沿多跳路徑稀釋</li><li>MOC：重構通訊以捕捉 multi-hop 依賴，建構結構化 multi-order evidence stream</li><li>Semantic-Topological Merging 演算法：在 token 約束內最大化語義保真</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>六個資料集、多種參數規模 backbone 上一致提升任務表現並降低通訊成本；具體數字未取得（abstract 未含）</li><li>開源程式碼（github.com/yao-guan/MOC）</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>workspace 拓樸限 parent↔child 兩層，multi-hop 稀釋問題在深層巢狀委派才顯著</li><li>merging 演算法本身的計算開銷未在 abstract 報告</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>「多跳路徑稀釋關鍵洞見」是 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md） 禁 child 間互通、通訊限 parent↔child 的獨立佐證：層數即失真放大器。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li>「token 約束內優化語義保真」與 <code>.claude/skills/output-compress</code> 的 fidelity gate 目標同構——壓縮上限應以保真為約束而非壓縮率最大化。⚠️ workspace 無深層 MAS，方法本體暫無落地面。</li></ul>',16)])])}const g=t(o,[["render",n]]);export{h as __pageData,g as default};
